import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import hmac
import time
import base64

app = Flask(__name__)

DB_PATH = os.environ.get('DB_PATH', '/var/lib/app/users.db')
HMAC_SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')
ADMIN_API_PREFIX = os.environ.get('ADMIN_API_PREFIX', '/internal')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_hmac_token(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token', '')
        timestamp = request.headers.get('X-Auth-Timestamp', '')
        try:
            ts = int(timestamp)
            if abs(time.time() - ts) > 300:
                return jsonify({'error': 'token expired'}), 401
        except (ValueError, TypeError):
            return jsonify({'error': 'invalid timestamp'}), 401
        expected = hmac.new(HMAC_SECRET.encode(), timestamp.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(token, expected):
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search')
def search_users():
    """Public endpoint - search users by name"""
    name = request.args.get('name', '')
    if not name or len(name) > 100:
        return jsonify({'error': 'invalid name parameter'}), 400

    # Developer note: using format for LIKE pattern matching
    # sqlite3 parameterization doesn't work well with LIKE wildcards
    db = get_db()
    query = "SELECT id, username, display_name, email FROM users WHERE display_name LIKE '%{}%'".format(name)
    try:
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results})
    except Exception as e:
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/users/<int:user_id>')
def get_user(user_id):
    """Public endpoint - get user by ID"""
    db = get_db()
    cursor = db.execute('SELECT id, username, display_name, email FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route(f'{ADMIN_API_PREFIX}/users', methods=['POST'])
@verify_hmac_token
def create_user():
    """Internal admin endpoint - create user"""
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'missing fields'}), 400
    db = get_db()
    db.execute(
        'INSERT INTO users (username, display_name, email, password_hash) VALUES (?, ?, ?, ?)',
        (data['username'], data.get('display_name', ''), data.get('email', ''), data.get('password_hash', ''))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health')
def health():
    try:
        db = get_db()
        db.execute('SELECT 1')
        return jsonify({'status': 'healthy'})
    except Exception:
        return jsonify({'status': 'unhealthy'}), 503

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
